python3 << 'PYEOF'
import json

with open('clauses_coreferential.json') as f:
    clauses = json.load(f)

for c in clauses:
    cid = c['clause_id']
    print(f"\n{'='*80}")
    print(f"[{cid}] domain={c['domain']}")
    print(f"  AMBIG: {c['ambiguous_clause'][:150]}")
    print(f"  UNAMBIG: {c['unambiguous_clause'][:150]}")
    print(f"  SCENARIO: {c['user_scenario'][:150]}")
    print(f"  INTERP: {c['possible_interpretations'][0][:120]}")
    print(f"          {c['possible_interpretations'][1][:120]}")

    # Layer 1: Check tool_responses for disambiguating fields
    leaks = []
    for tr in c.get('tool_responses', []):
        resp = tr['response']
        resp_str = json.dumps(resp)
        # Check for explicit ages
        if '"age"' in resp_str:
            leaks.append(f"  LEAK: {tr['tool_name']} has explicit 'age' field")
        if 'wrong_item' in resp_str.lower():
            leaks.append(f"  LEAK: {tr['tool_name']} has 'wrong_item' status")
        if 'complaint_count' in resp_str:
            leaks.append(f"  LEAK: {tr['tool_name']} has complaint_count")
        if '"label"' in resp_str and ('personal' in resp_str or 'corporate' in resp_str):
            leaks.append(f"  LEAK: {tr['tool_name']} has labeled payment methods")
        # Check for any status field that resolves ambiguity
        if 'actual_retail_value' in resp_str or 'actual_product' in resp_str:
            leaks.append(f"  LEAK: {tr['tool_name']} has actual_product/value info")
        if 'charged_card' in resp_str:
            leaks.append(f"  LEAK: {tr['tool_name']} has charged_card in response")
        if 'date_of_birth' in resp_str:
            leaks.append(f"  LEAK: {tr['tool_name']} has date_of_birth")

    if leaks:
        for l in leaks:
            print(l)
    else:
        print("  LEAK CHECK: No obvious leaks detected (manual review needed)")
PYEOF

